from collections import Counter, deque

def components(grid, bg):
    R,C=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(R):
      for c in range(C):
        if grid[r][c]==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          x,y=q.pop(); comp.append((x,y))
          for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            if 0<=nx<R and 0<=ny<C and grid[nx][ny]!=bg and (nx,ny) not in seen:
              seen.add((nx,ny)); q.append((nx,ny))
        comps.append(comp)
    return comps
